impl Document {
    pub(crate) fn compare_code(
        &self,
        other: &Document,
        a: &Code,
        b: &Code,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        let list_a = a.get_artifact_descriptors();
        let list_b = b.get_artifact_descriptors();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: ARTIFACT_DESCRIPTORS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.autosar_engineering_objects.get(*x).ok_or_else(|| {
                format!("{path}.ARTIFACT_DESCRIPTORS[{index}]: id not found in own arena")
            })?;
            let y = other.autosar_engineering_objects.get(*y).ok_or_else(|| {
                format!("{path}.ARTIFACT_DESCRIPTORS[{index}]: id not found in other arena")
            })?;
            self.compare_autosar_engineering_object(
                other,
                x,
                y,
                &format!("{path}.ARTIFACT_DESCRIPTORS[{index}]"),
            )?;
        }
        let list_a = a.get_callback_header_refs();
        let list_b = b.get_callback_header_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: CALLBACK_HEADER_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.CALLBACK_HEADER_REFS[{index}] mismatch"));
            }
        }
        Ok(())
    }

    pub(crate) fn compare_compiler(
        &self,
        other: &Document,
        a: &Compiler,
        b: &Compiler,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        if a.get_name() != b.get_name() {
            return Err(format!("{path}: NAME mismatch"));
        }
        if a.get_options() != b.get_options() {
            return Err(format!("{path}: OPTIONS mismatch"));
        }
        if a.get_vendor() != b.get_vendor() {
            return Err(format!("{path}: VENDOR mismatch"));
        }
        if a.get_version() != b.get_version() {
            return Err(format!("{path}: VERSION mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_dependency_on_artifact(
        &self,
        other: &Document,
        a: &DependencyOnArtifact,
        b: &DependencyOnArtifact,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_artifact_descriptor() != b.get_artifact_descriptor() {
            return Err(format!("{path}: ARTIFACT_DESCRIPTOR mismatch"));
        }
        let list_a = a.get_usages();
        let list_b = b.get_usages();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: USAGES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.USAGES[{index}] mismatch"));
            }
        }
        Ok(())
    }

    pub(crate) fn compare_implementation(
        &self,
        other: &Document,
        a: &Implementation,
        b: &Implementation,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        if a.get_build_action_manifest_ref() != b.get_build_action_manifest_ref() {
            return Err(format!("{path}: BUILD_ACTION_MANIFEST_REF mismatch"));
        }
        let list_a = a.get_code_descriptors();
        let list_b = b.get_code_descriptors();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: CODE_DESCRIPTORS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.codes.get(*x).ok_or_else(|| {
                format!("{path}.CODE_DESCRIPTORS[{index}]: id not found in own arena")
            })?;
            let y = other.codes.get(*y).ok_or_else(|| {
                format!("{path}.CODE_DESCRIPTORS[{index}]: id not found in other arena")
            })?;
            self.compare_code(other, x, y, &format!("{path}.CODE_DESCRIPTORS[{index}]"))?;
        }
        let list_a = a.get_compilers();
        let list_b = b.get_compilers();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: COMPILERS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .compilers
                .get(*x)
                .ok_or_else(|| format!("{path}.COMPILERS[{index}]: id not found in own arena"))?;
            let y = other
                .compilers
                .get(*y)
                .ok_or_else(|| format!("{path}.COMPILERS[{index}]: id not found in other arena"))?;
            self.compare_compiler(other, x, y, &format!("{path}.COMPILERS[{index}]"))?;
        }
        let list_a = a.get_generated_artifacts();
        let list_b = b.get_generated_artifacts();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: GENERATED_ARTIFACTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.dependency_on_artifacts.get(*x).ok_or_else(|| {
                format!("{path}.GENERATED_ARTIFACTS[{index}]: id not found in own arena")
            })?;
            let y = other.dependency_on_artifacts.get(*y).ok_or_else(|| {
                format!("{path}.GENERATED_ARTIFACTS[{index}]: id not found in other arena")
            })?;
            self.compare_dependency_on_artifact(
                other,
                x,
                y,
                &format!("{path}.GENERATED_ARTIFACTS[{index}]"),
            )?;
        }
        let list_a = a.get_hw_element_refs();
        let list_b = b.get_hw_element_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: HW_ELEMENT_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.HW_ELEMENT_REFS[{index}] mismatch"));
            }
        }
        let list_a = a.get_linkers();
        let list_b = b.get_linkers();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: LINKERS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .linkers
                .get(*x)
                .ok_or_else(|| format!("{path}.LINKERS[{index}]: id not found in own arena"))?;
            let y = other
                .linkers
                .get(*y)
                .ok_or_else(|| format!("{path}.LINKERS[{index}]: id not found in other arena"))?;
            self.compare_linker(other, x, y, &format!("{path}.LINKERS[{index}]"))?;
        }
        if a.get_mc_support() != b.get_mc_support() {
            return Err(format!("{path}: MC_SUPPORT mismatch"));
        }
        if a.get_programming_language() != b.get_programming_language() {
            return Err(format!("{path}: PROGRAMMING_LANGUAGE mismatch"));
        }
        let list_a = a.get_required_artifacts();
        let list_b = b.get_required_artifacts();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: REQUIRED_ARTIFACTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.dependency_on_artifacts.get(*x).ok_or_else(|| {
                format!("{path}.REQUIRED_ARTIFACTS[{index}]: id not found in own arena")
            })?;
            let y = other.dependency_on_artifacts.get(*y).ok_or_else(|| {
                format!("{path}.REQUIRED_ARTIFACTS[{index}]: id not found in other arena")
            })?;
            self.compare_dependency_on_artifact(
                other,
                x,
                y,
                &format!("{path}.REQUIRED_ARTIFACTS[{index}]"),
            )?;
        }
        let list_a = a.get_required_generator_tools();
        let list_b = b.get_required_generator_tools();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: REQUIRED_GENERATOR_TOOLS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.dependency_on_artifacts.get(*x).ok_or_else(|| {
                format!("{path}.REQUIRED_GENERATOR_TOOLS[{index}]: id not found in own arena")
            })?;
            let y = other.dependency_on_artifacts.get(*y).ok_or_else(|| {
                format!("{path}.REQUIRED_GENERATOR_TOOLS[{index}]: id not found in other arena")
            })?;
            self.compare_dependency_on_artifact(
                other,
                x,
                y,
                &format!("{path}.REQUIRED_GENERATOR_TOOLS[{index}]"),
            )?;
        }
        if a.get_resource_consumption() != b.get_resource_consumption() {
            return Err(format!("{path}: RESOURCE_CONSUMPTION mismatch"));
        }
        if a.get_swc_bsw_mapping_ref() != b.get_swc_bsw_mapping_ref() {
            return Err(format!("{path}: SWC_BSW_MAPPING_REF mismatch"));
        }
        if a.get_sw_version() != b.get_sw_version() {
            return Err(format!("{path}: SW_VERSION mismatch"));
        }
        if a.get_used_code_generator() != b.get_used_code_generator() {
            return Err(format!("{path}: USED_CODE_GENERATOR mismatch"));
        }
        if a.get_vendor_id() != b.get_vendor_id() {
            return Err(format!("{path}: VENDOR_ID mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_implementation_props(
        &self,
        other: &Document,
        a: &ImplementationProps,
        b: &ImplementationProps,
        path: &str,
    ) -> Result<(), String> {
        self.compare_referrable(other, a.base(), b.base(), path)?;
        if a.get_symbol() != b.get_symbol() {
            return Err(format!("{path}: SYMBOL mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_linker(
        &self,
        other: &Document,
        a: &Linker,
        b: &Linker,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        if a.get_name() != b.get_name() {
            return Err(format!("{path}: NAME mismatch"));
        }
        if a.get_options() != b.get_options() {
            return Err(format!("{path}: OPTIONS mismatch"));
        }
        if a.get_vendor() != b.get_vendor() {
            return Err(format!("{path}: VENDOR mismatch"));
        }
        if a.get_version() != b.get_version() {
            return Err(format!("{path}: VERSION mismatch"));
        }
        Ok(())
    }
}
